import java.util.*;
import java.io.*;

public class Main {

    static final int INF_CONST = 1000000000;
    static final int MAX_SIZE = 11;
    static final int MAX_NODES = 205;
    static final int DIRECTIONS_COUNT = 4;
    static final int[] dy = {-1, 0, 1, 0};
    static final int[] dx = {0, -1, 0, 1};

    static int n, t;
    static char[][] grid = new char[MAX_SIZE][MAX_SIZE];
    static char[][] backup = new char[MAX_SIZE][MAX_SIZE];
    static int start_i, start_j;
    static int[][] dist_b = new int[MAX_SIZE][MAX_SIZE];
    static int[][] dist_bk = new int[MAX_SIZE][MAX_SIZE];
    static boolean[][] can_reach = new boolean[MAX_SIZE][MAX_SIZE];
    static int total_nodes;
    static int[][] cap = new int[MAX_SIZE][MAX_SIZE];
    static List<Integer>[] adj_list = new ArrayList[MAX_NODES];

    static int[] flow = new int[MAX_NODES];
    static int[] parent = new int[MAX_NODES];

    static class Point implements Comparable<Point> {
        int first, second;

        Point(int first, int second) {
            this.first = first;
            this.second = second;
        }

        public int compareTo(Point o) {
            return Integer.compare(o.first, this.first);
        }
    }

    public static void first_bfs() {
        for (int i = 0; i < MAX_SIZE; i++) {
            for (int j = 0; j < MAX_SIZE; j++) {
                cap[i][j] = t;
            }
        }
        cap[start_i][start_j] = 0;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(start_i, start_j));
        while (!q.isEmpty()) {
            Point v = q.poll();
            int d = cap[v.first][v.second];
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int ni = v.first + dy[dir];
                int nj = v.second + dx[dir];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] != 'Y'
                        && d + 1 < cap[ni][nj]) {
                    cap[ni][nj] = d + 1;
                    q.offer(new Point(ni, nj));
                }
            }
        }
    }

    public static void second_bfs(int sr, int sc) {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(dist_bk[i], INF_CONST);
        }
        dist_bk[sr][sc] = 0;
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(can_reach[i], false);
        }
        can_reach[sr][sc] = true;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(sr, sc));
        while (!q.isEmpty()) {
            Point v = q.poll();
            int d = dist_bk[v.first][v.second];
            can_reach[v.first][v.second] = d <= cap[v.first][v.second];
            if (d >= cap[v.first][v.second]) continue;
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int ni = v.first + dy[dir];
                int nj = v.second + dx[dir];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] != 'Y'
                        && d + 1 < dist_bk[ni][nj]) {
                    dist_bk[ni][nj] = d + 1;
                    q.offer(new Point(ni, nj));
                }
            }
        }
    }

    public static void run_bfs(int sr, int sc, int[][] d, int INF_VAL) {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(d[i], INF_VAL);
        }
        d[sr][sc] = 0;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(sr, sc));
        while (!q.isEmpty()) {
            Point v = q.poll();
            int d_v = d[v.first][v.second];
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int ni = v.first + dy[dir];
                int nj = v.second + dx[dir];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] != 'Y'
                        && d_v + 1 < d[ni][nj]) {
                    d[ni][nj] = d_v + 1;
                    q.offer(new Point(ni, nj));
                }
            }
        }
    }

    public static int max_flow() {
        Arrays.fill(flow, 0);
        flow[0] = INF_CONST;
        PriorityQueue<Point> pq = new PriorityQueue<>();
        pq.offer(new Point(INF_CONST, 0));
        while (!pq.isEmpty()) {
            Point top = pq.poll();
            int v = top.second;
            int f = top.first;
            if (flow[v] != f)
                continue;
            for (int u : adj_list[v]) {
                int newFlow = Math.min(f, cap[v][u]);
                if (newFlow > flow[u]) {
                    flow[u] = newFlow;
                    parent[u] = v;
                    pq.offer(new Point(flow[u], u));
                }
            }
        }
        int v = total_nodes - 1;
        if (flow[v] == 0)
            return 0;
        int total_flow = flow[v];
        while (v != 0) {
            int u = parent[v];
            cap[u][v] -= total_flow;
            cap[v][u] += total_flow;
            v = u;
        }
        return total_flow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < MAX_NODES; i++) {
            adj_list[i] = new ArrayList<>();
        }
        n = sc.nextInt();
        t = sc.nextInt();
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'Z') {
                    start_i = i;
                    start_j = j;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                backup[i][j] = line.charAt(j);
            }
        }
        first_bfs();
        total_nodes = 2 * n * n + 2;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(grid[i][j]) && grid[i][j] > '0') {
                    int v = i * n + j + 1;
                    cap[0][v] = grid[i][j] - '0';

                    adj_list[0].add(v);
                    adj_list[v].add(0);

                    second_bfs(i, j);
                    for (int i2 = 0; i2 < n; i2++) {
                        for (int j2 = 0; j2 < n; j2++) {
                            if (can_reach[i2][j2] && Character.isDigit(backup[i2][j2]) && backup[i2][j2] > '0') {
                                int u = n * n + i2 * n + j2 + 1;
                                cap[v][u] = INF_CONST;
                                adj_list[v].add(u);
                                adj_list[u].add(v);
                            }
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (Character.isDigit(backup[i][j]) && backup[i][j] > '0') {
                    int u = n * n + i * n + j + 1;
                    cap[u][total_nodes - 1] = backup[i][j] - '0';

                    adj_list[u].add(total_nodes - 1);
                    adj_list[total_nodes - 1].add(u);
                }
            }
        }

        int total_flow_value = 0;
        int flow;
        while ((flow = max_flow()) != 0) {
            total_flow_value += flow;
        }

        System.out.println(total_flow_value);
    }
}
